"""Activate the 11 source-validated creators requested by Jesse; no bot code deployment."""
import base64,gzip,json,pathlib,shlex,subprocess,time
source="import json,subprocess\nexpected='sha256:9649329a00bd20fe06499f8238e1e51713381521af00d4cdc67505e1064f724a'\nfor name in ['twin-v2-bot-1','twin-v2-dash-1']:\n d=json.loads(subprocess.check_output(['docker','inspect',name],text=True))[0]\n assert d['State']['Running'] and d['Image']==expected\ncode=\"\\nimport fs from 'node:fs';\\nimport path from 'node:path';\\nimport assert from 'node:assert/strict';\\nimport {createHash} from 'node:crypto';\\nimport {config} from './src/config.ts';\\nimport {mapFromV1} from './src/girls/map-v1.ts';\\nimport {validateVars,render} from './src/girls/template.ts';\\nimport {requestHandover,clearHandover,activeRequest} from './src/handover.ts';\\nimport {loadRawCatalogue,catalogueFromRaw} from './src/media.ts';\\nconst targets=[{\\\"slug\\\":\\\"alanna-pow\\\",\\\"id\\\":\\\"6ca0782d-b5cf-433d-8329-f3ef7ec5f011\\\",\\\"profileHash\\\":\\\"ef5468fe725e6032bf2bef9d0a4c809cffe4ea97e086c08f19133d58d7aa22b3\\\"},{\\\"slug\\\":\\\"allison-parker\\\",\\\"id\\\":\\\"e0464c19-d5b7-4154-ba46-a60a2ed2a8a3\\\",\\\"profileHash\\\":\\\"927a811d8d1c3e92785d87aaa58128bc141ea4ebff90954a1cf61b289ae4a3b2\\\"},{\\\"slug\\\":\\\"cat-chase\\\",\\\"id\\\":\\\"046fd9b0-7771-49ef-a7df-9d2c518575cc\\\",\\\"profileHash\\\":\\\"dc6a125e436a6c615248566bdc1cf67c41e216f16051521cbb3c1a42e32b50ea\\\"},{\\\"slug\\\":\\\"dakota-lyn\\\",\\\"id\\\":\\\"85d226d6-91f1-4082-9534-d500a68ed537\\\",\\\"profileHash\\\":\\\"4ce18387c60a2c976ba52ff4baa8eb7292b2ab7a50242d4ffef5fb12863b79d5\\\"},{\\\"slug\\\":\\\"dreka-cakez\\\",\\\"id\\\":\\\"c92560e7-1dd9-4e62-b5c3-04a30fbe4925\\\",\\\"profileHash\\\":\\\"448f9c42d296e4a467bcf5d925b917c6b932709432e601b9c39985baa0cce1dd\\\"},{\\\"slug\\\":\\\"olivia-jade\\\",\\\"id\\\":\\\"7c2e9452-1d4e-475c-86ef-07a797f52ce5\\\",\\\"profileHash\\\":\\\"70ba1390218c3dc8d6e975c5445261ece7f06449e3186939bbe05c0f39be63d9\\\"},{\\\"slug\\\":\\\"tammy\\\",\\\"id\\\":\\\"7eae9772-eb7c-4a24-a54f-51cbb28f1def\\\",\\\"profileHash\\\":\\\"501a4500305502368c79ece7992b46ee41bf5bc8e4e0cdd293eb6bea8543ca09\\\"},{\\\"slug\\\":\\\"toochi\\\",\\\"id\\\":\\\"bfaf6235-6c3b-4369-8d5c-c7068b08bea2\\\",\\\"profileHash\\\":\\\"f05e54195677fbf50dcfd81b72361ef7b1207a747d9eaa78f8867dbf8afeabae\\\"},{\\\"slug\\\":\\\"trashy\\\",\\\"id\\\":\\\"3484f7d9-0cda-4f52-84de-e104c238ce5e\\\",\\\"profileHash\\\":\\\"aa24c2276b2cd66d27cf24ffc6b7f863d76d80a46b931da30fbcf158bad81372\\\"},{\\\"slug\\\":\\\"tru-kait\\\",\\\"id\\\":\\\"02a49e27-606d-4f20-9472-fab39255753f\\\",\\\"profileHash\\\":\\\"8d329b9562930c9144e58ab582bd8163b7c7871a2ffdadf9c3f8aea315496c0a\\\"},{\\\"slug\\\":\\\"bethany-marquez\\\",\\\"id\\\":\\\"4fff7866-c7e9-4af2-926a-36e727c0a77f\\\",\\\"profileHash\\\":\\\"215fa273fc53b402577e8d639787e07d93ff4c86f286797ef070423dc0fb935e\\\"}];\\nconst connections=[{\\\"slug\\\":\\\"alanna-pow\\\",\\\"id\\\":\\\"VSaNxwVmiFVVAwAA5zsJRHQDTh4\\\"},{\\\"slug\\\":\\\"alanna-pow\\\",\\\"id\\\":\\\"W25LefCtGVcgAgAAgm5gl7Ubk0k\\\"},{\\\"slug\\\":\\\"allison-parker\\\",\\\"id\\\":\\\"QyTby2F6qFRFBAAAd22gGpV2u8w\\\"},{\\\"slug\\\":\\\"bethany-marquez\\\",\\\"id\\\":\\\"hQWc7AfYoFR3BQAAdaQwfD9TfRs\\\"},{\\\"slug\\\":\\\"cat-chase\\\",\\\"id\\\":\\\"olaA63EfWEZVAQAA7_1vlUKv28c\\\"},{\\\"slug\\\":\\\"cat-chase\\\",\\\"id\\\":\\\"5qa6NMV-UUaUAQAAW3CBojYOJ3s\\\"},{\\\"slug\\\":\\\"cat-chase\\\",\\\"id\\\":\\\"sT2NefC0UUf0AAAAkRl2HObbMDM\\\"},{\\\"slug\\\":\\\"dakota-lyn\\\",\\\"id\\\":\\\"-ugQLEGu0FcKBgAA4sQEQqe1agU\\\"},{\\\"slug\\\":\\\"dreka-cakez\\\",\\\"id\\\":\\\"GWPAm1o9wES8AQAA9wUzMmQYIao\\\"},{\\\"slug\\\":\\\"dreka-cakez\\\",\\\"id\\\":\\\"YDvXcAoNkFTWAgAAq_PlJSJgeJo\\\"},{\\\"slug\\\":\\\"olivia-jade\\\",\\\"id\\\":\\\"g9oTMly0aFbyBAAAHDX1kG85JiY\\\"},{\\\"slug\\\":\\\"tammy\\\",\\\"id\\\":\\\"BuDshb2UqVeXAgAAZbja4QmBsUI\\\"},{\\\"slug\\\":\\\"toochi\\\",\\\"id\\\":\\\"Xg1u5X2KUVQQBAAA6CEKwOTMP7A\\\"},{\\\"slug\\\":\\\"trashy\\\",\\\"id\\\":\\\"yV1GQVzhIFb2AgAAJNW4iY0uCkQ\\\"},{\\\"slug\\\":\\\"tru-kait\\\",\\\"id\\\":\\\"Tmt2-YDEiFdZBQAAGznA4DamhLo\\\"}];\\nfunction prepare(c){\\n const v=mapFromV1(c).vars,f=c.intake?.fields??{};\\n const sentences=x=>String(x??'').split(/(?<=[.!?])\\\\s+|\\\\n/).map(x=>x.trim()).filter(Boolean);\\n const compatible=x=>sentences(x).filter(s=>!/capitaliz|asterisk|stage direction|stacked|back to back|several messages|double and triple|its own message|one word on its own|question back.*every|question back most|his name constantly|first name inside almost|emoji/i.test(s)).join(' ');\\n v.DAILY_LIFE ||= compatible(f.life_tastes) || 'No additional daily routine is specified.';\\n if(!v.PERSONALITY || v.PERSONALITY==='custom') v.PERSONALITY=compatible(f.quirks) || 'No separate personality description is recorded.';\\n v.TEXT_EXAMPLES ||= String(f.example_texts??'').split(/\\\\r?\\\\n/).map(x=>x.trim()).filter(x=>x&&!/\\\\b(?:marc|marco|james|oscar|elijah)\\\\b|\\\\*/i.test(x)).slice(0,4).map(x=>JSON.stringify(x.toLowerCase())).join(' / ') || 'No approved example texts are recorded.';\\n v.SIGNATURE_WORDS = c.catchphrases?.length ? c.catchphrases.join(', ') : 'not separately specified';\\n v.SEX_ROLE = 'not assigned a fixed role in the saved creator profile.';\\n if(f.flirt_nsfw) v.SEX_PACE = sentences(f.flirt_nsfw).slice(0,1).join(' ');\\n v.SEX_EXTRAS ||= 'No additional preferences are recorded.';\\n v.SOCIALS ||= c.business_username ? 'telegram @'+c.business_username : 'No additional public handles are recorded.';\\n v.WORK_ANSWER ||= c.cover_story || c.known_for || 'i keep that part of my life private';\\n v.LOVE_REPLY ||= 'respond warmly without promising a real relationship';\\n v.MEET_REPLY = 'i keep things online here';\\n v.PET_NAMES ||= 'only by a name he has actually given you';\\n v.OFF_LIMITS=[v.OFF_LIMITS,c.hard_limits?.length?'Never go into or agree to: '+c.hard_limits.join(', ')+'.':'',c.hard_limits_extra,...sentences(f.notes).filter(s=>/^Never /i.test(s))].filter(Boolean).join('\\\\n') || 'Keep private personal details private. Respect the hard limits below.';\\n if(c.slug==='olivia-jade') v.LOOKS += '\\\\n'+sentences(f.notes).find(s=>s.startsWith('Trans woman'));\\n if(/never claim a real romantic relationship|exclusivity or love/i.test(v.OFF_LIMITS)) v.LOVE_REPLY='respond warmly without claiming real love, exclusivity or a romantic relationship';\\n const unknown={LOOKS:'No further physical details are specified; do not invent them.',HERITAGE:'No further heritage or language details are specified.',LOVE_LIFE:'No further relationship details are specified; keep them private.',LIKES:'No further personal preferences are specified.',VALUES:'No further personal values are specified.'};\\n for(const [key,value] of Object.entries(unknown)) v[key] ||= value;\\n for(const key of Object.keys(v)) v[key]=String(v[key]??'').replace(/\\\\s*[\\\\u2013\\\\u2014]\\\\s*/g,', ');\\n const errors=validateVars(v);\\n if(!errors.length){const prompt=render(v); if(/\\\\{\\\\{[A-Z_]+\\\\}\\\\}/.test(prompt))throw Error('Unresolved prompt');}\\n return {vars:v,errors};\\n}\\nconst stable=x=>JSON.stringify(x,Object.keys(x).sort());\\nconst hash=x=>createHash('sha256').update(stable(x)).digest('hex');\\nconst headers={apikey:config.supabaseKey,Authorization:'Bearer '+config.supabaseKey,'Content-Type':'application/json'};\\nconst db=async(p,body)=>{const r=await fetch(config.supabaseUrl+'/rest/v1/'+p,{headers,...(body?{method:'POST',body:JSON.stringify(body)}:{}),signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error('database '+r.status+' '+p.split('?')[0]);return r.json();};\\nconst monitor=async(p,body)=>{const r=await fetch('http://127.0.0.1:4300'+p,{headers:{'Content-Type':'application/json'},...(body?{method:'POST',body:JSON.stringify(body)}:{}),signal:AbortSignal.timeout(90000)});if(!r.ok)throw Error('monitor '+r.status);return r.json();};\\nconst sleep=ms=>new Promise(r=>setTimeout(r,ms));\\nconst fleet=()=>JSON.parse(fs.readFileSync(path.join(config.dataDir,'_fleet.json'),'utf8'));\\nconst say=x=>console.log('V2_MIGRATION '+JSON.stringify(x));\\nassert.equal(process.env.GIT_SHA,'86b0ad199ea33fd7855f1c0dd54cc355f706e7f5');\\nconst root=path.join(config.dataDir,'_operator_backups','remaining-creators-v2-20261013');\\nfs.mkdirSync(root,{recursive:true,mode:0o700});\\nconst lock=path.join(root,'operation.lock');\\nconst fd=fs.openSync(lock,'wx',0o600);fs.writeSync(fd,new Date().toISOString());fs.closeSync(fd);\\nlet holds=new Set(),switched=new Set(),released=new Set();\\nconst before=await db('clones?select=*&order=slug');\\nconst original=new Map(before.map(c=>[c.id,c]));\\nconst prepared=new Map();\\nconst priorFleet=fleet();\\nassert.ok(Date.now()-Date.parse(priorFleet.at)<90000,'Fleet stale');\\nconst priorRunning=Object.entries(priorFleet.girls).filter(([,v])=>v.status==='running').map(([slug])=>slug);\\nassert.equal(priorRunning.length,5);\\nassert.equal(before.find(c=>c.slug==='sania-mallory')?.status,'paused');\\nfor(const t of targets){\\n const c=original.get(t.id);assert.equal(c?.slug,t.slug);assert.equal(c.engine,'live');assert.equal(c.status,'active');assert.equal(c.v2_vars,null);assert.equal(c.v2_credits_enabled,false);assert.equal(c.v2_memory_enabled,false);assert.ok(!priorFleet.girls[t.slug]);\\n assert.ok(!activeRequest(config.dataDir,t.slug),'Handover already open');\\n const p=prepare(c);assert.deepEqual(p.errors,[]);assert.equal(hash(p.vars),t.profileHash,'Profile source changed: '+t.slug);\\n const open=await db('rpc/v2credit_open_work',{p_clone_id:t.id});assert.ok(open.ok===true&&open.reserved_turns===0);\\n prepared.set(t.id,p.vars);\\n}\\nconst safe=before.map(({bot_token,elevenlabs_api_key,account_phone,voice_id,...c})=>c);\\nfs.writeFileSync(path.join(root,'before.json'),JSON.stringify(safe,null,2),{flag:'wx',mode:0o600});\\nfs.writeFileSync(path.join(root,'profiles.json'),JSON.stringify(targets.map(t=>({...t,vars:prepared.get(t.id)})),null,2),{flag:'wx',mode:0o600});\\nconst business=[];\\nfor(const t of targets){\\n const c=original.get(t.id),list=connections.filter(x=>x.slug===t.slug);let enabled=0,matching=0;\\n for(const x of list){\\n  const r=await fetch('https://api.telegram.org/bot'+c.bot_token+'/getBusinessConnection?business_connection_id='+encodeURIComponent(x.id),{signal:AbortSignal.timeout(15000)}).then(r=>r.json());\\n  if(r.ok&&r.result.is_enabled&&(r.result.rights?.can_reply??r.result.can_reply)){enabled++;if((r.result.user?.username??'').toLowerCase()===(c.business_username??'').toLowerCase())matching++;}\\n }\\n business.push({slug:t.slug,enabledConnections:enabled,matchingUsername:matching});\\n}\\nfs.writeFileSync(path.join(root,'business-preflight.json'),JSON.stringify(business),{mode:0o600});\\nsay({phase:'validated',ready:targets.length,business});\\ntry{\\n for(const t of targets){const r=await monitor('/api/girls/details',{girl:t.slug,vars:prepared.get(t.id)});assert.equal(r.ok,true,'Profile save: '+t.slug);}\\n for(const t of targets){requestHandover(config.dataDir,t.slug);holds.add(t.slug);}\\n const switchedAt={};\\n for(const t of targets){\\n  switchedAt[t.id]=new Date().toISOString();\\n  const r=await monitor('/api/girls/engine',{id:t.id,engine:'v2'});assert.equal(r.ok,true,'Engine switch '+t.slug+': '+r.error);switched.add(t.id);\\n }\\n say({phase:'waiting_for_v1_drain',count:switched.size});\\n const receipts=new Map();\\n const min=Object.values(switchedAt).sort()[0];\\n const deadline=Date.now()+135000;\\n while(Date.now()<deadline&&receipts.size<targets.length){\\n  const qp=new URLSearchParams({select:'id,ts,clone_id,message',source:'eq.runtime',ts:'gte.'+min,clone_id:'in.('+targets.map(x=>x.id).join(',')+')',order:'id.desc',limit:'100'});\\n  const events=await db('system_logs?'+qp);\\n  for(const e of events)if(e.message.includes('switched to the external V2 engine; polling stopped')&&Date.parse(e.ts)>=Date.parse(switchedAt[e.clone_id]))receipts.set(e.clone_id,{id:e.id,at:e.ts});\\n  if(receipts.size<targets.length)await sleep(2000);\\n }\\n assert.equal(receipts.size,targets.length,'V1 did not confirm every drain');\\n // The fleet was held while V1 stopped polling and drained its admitted turns.\\n for(const t of targets){assert.ok(activeRequest(config.dataDir,t.slug),'Handover expired');clearHandover(config.dataDir,t.slug);holds.delete(t.slug);released.add(t.id);}\\n fs.writeFileSync(path.join(root,'handover.json'),JSON.stringify({switchedAt,receipts:Object.fromEntries(receipts)}),{mode:0o600});\\n const until=Date.now()+120000;\\n while(Date.now()<until){\\n  const f=fleet();\\n  if(targets.every(t=>f.girls[t.slug]?.status==='running'))break;\\n  await sleep(2500);\\n }\\n const nowFleet=fleet();\\n for(const slug of priorRunning)assert.equal(nowFleet.girls[slug]?.status,'running','Prior V2 stopped: '+slug);\\n const after=await db('clones?select=*&order=slug');\\n const outcomes=[];\\n for(const t of targets){\\n  const c=after.find(c=>c.id===t.id),old=original.get(t.id),rt=nowFleet.girls[t.slug];\\n  assert.equal(c.engine,'v2');assert.equal(hash(c.v2_vars),t.profileHash);assert.equal(rt?.status,'running','V2 startup: '+t.slug);\\n  assert.equal(rt.credits?.applied?.enabled,c.v2_credits_enabled,'Applied credits mismatch');assert.equal(rt.memory?.applied?.enabled,c.v2_memory_enabled,'Applied memory mismatch');assert.equal(rt.tips?.applied?.enabled,c.tips_enabled,'Applied tips mismatch');\\n  const omit=({engine,v2_vars,...x})=>x;assert.deepEqual(omit(c),omit(old),'Unrelated creator settings changed: '+t.slug);\\n  const details=await monitor('/api/girls/details?girl='+encodeURIComponent(t.slug));assert.deepEqual(details.errors,[]);\\n  assert.equal(hash(details.vars),t.profileHash);\\n  const shown=details.parts.filter(x=>!x.optional).map(x=>x.text??'').join('');\\n  assert.equal(shown,render(c.v2_vars),'Displayed prompt mismatch: '+t.slug);\\n  const cat=catalogueFromRaw(await loadRawCatalogue(c.id));\\n  outcomes.push({slug:t.slug,name:t.name??c.name,engine:c.engine,runtime:rt.status,botUsername:rt.botUsername,startedAt:rt.startedAt,v1Receipt:receipts.get(t.id),photos:cat.filter(x=>x.kind==='photo').length,videos:cat.filter(x=>x.kind==='video').length,tipsPreserved:c.tips_enabled===old.tips_enabled,creditsPreserved:c.v2_credits_enabled===old.v2_credits_enabled,memoryPreserved:c.v2_memory_enabled===old.v2_memory_enabled,promptVerified:true,business:business.find(x=>x.slug===t.slug)});\\n }\\n for(const c of before.filter(c=>!targets.some(t=>t.id===c.id)))assert.deepEqual(after.find(x=>x.id===c.id),c,'Untargeted creator changed: '+c.slug);\\n const report={at:new Date().toISOString(),success:true,migrated:outcomes,remaining:after.filter(c=>c.engine!=='v2').map(c=>({name:c.name,slug:c.slug,reason:'No recorded birth date; existing V2 validation requires YYYY-MM-DD'})),saniaPaused:after.find(c=>c.slug==='sania-mallory')?.status==='paused',priorV2Preserved:true,onlyChangedColumns:['engine','v2_vars'],botCodeChanged:false,messagesSentByMigration:0,modelCallsByMigration:0,backup:root};\\n fs.writeFileSync(path.join(root,'result.json'),JSON.stringify(report,null,2),{mode:0o600});say(report);\\n}catch(e){\\n // Roll back only switches still held before V2 activation; never restore chat/payment snapshots.\\n const rollback=[];\\n for(const t of targets.filter(t=>switched.has(t.id)&&!released.has(t.id))){\\n  try{const r=await monitor('/api/girls/engine',{id:t.id,engine:'live'});rollback.push({slug:t.slug,ok:r.ok===true});if(r.ok)switched.delete(t.id);}catch{rollback.push({slug:t.slug,ok:false});}\\n }\\n const fail={at:new Date().toISOString(),success:false,error:String(e.message).slice(0,300),rollback,activated:[...released].map(id=>targets.find(t=>t.id===id)?.slug)};\\n fs.writeFileSync(path.join(root,'failure.json'),JSON.stringify(fail,null,2),{mode:0o600});say(fail);throw e;\\n}finally{\\n for(const slug of holds){const t=targets.find(t=>t.slug===slug);if(!switched.has(t.id))clearHandover(config.dataDir,slug);}\\n fs.unlinkSync(lock);\\n}\\n\"\np=subprocess.run(['docker','exec','-i','twin-v2-dash-1','node','--import','tsx','--input-type=module'],input=code,text=True,capture_output=True,timeout=380)\nfor line in p.stdout.splitlines():\n if line.startswith('V2_MIGRATION '): print(line,flush=True)\nif p.returncode: raise RuntimeError(p.stderr[-800:])\nfor name in ['twin-v2-bot-1','twin-v2-dash-1']:\n assert subprocess.check_output(['docker','inspect','-f','{{.Image}}',name],text=True).strip()==expected\n"
packed=base64.b64encode(gzip.compress(source.encode())).decode()
host="import base64,gzip;exec(compile(gzip.decompress(base64.b64decode("+repr(packed)+")),'v2-remaining','exec'))"
params={'commands':['python3 -c '+shlex.quote(host)],'executionTimeout':['420']}
p=pathlib.Path('/tmp/v2-remaining.json');p.write_text(json.dumps(params))
cid=subprocess.check_output(['aws','ssm','send-command','--instance-ids','i-0584d283506f3f6be','--document-name','AWS-RunShellScript','--parameters','file://'+str(p),'--comment','Activate requested ready creator accounts on V2','--query','Command.CommandId','--output','text'],text=True).strip()
print(json.dumps({'commandId':cid}),flush=True)
for _ in range(145):
 try:r=json.loads(subprocess.check_output(['aws','ssm','get-command-invocation','--command-id',cid,'--instance-id','i-0584d283506f3f6be','--output','json'],text=True,stderr=subprocess.DEVNULL))
 except subprocess.CalledProcessError:time.sleep(3);continue
 if r['Status'] in ['Success','Failed','Cancelled','TimedOut']:break
 time.sleep(3)
else:raise RuntimeError('Readiness check incomplete')
print(r.get('StandardOutputContent',''),flush=True)
if r['Status']!='Success':
 print(r.get('StandardErrorContent','')[-1200:],flush=True)
 raise RuntimeError('Readiness check failed')
